-- =====================================================================
-- Lot 600 — 602 champs a remplir et 1418 associations de tags
--
-- Les champs sont ce que le membre renseigne avant de copier. Depuis que le
-- texte ne depend plus de l'IA, c'est la seule personnalisation d'une carte.
-- La borne tient en base : trois au plus en regime standard, quatre en
-- marketing, et l'extraction a verifie que les 642 cartes la respectent.
--
-- Les champs sont reecrits entierement pour les cartes du lot, jamais
-- fusionnes : un champ retire du CSV doit disparaitre de la fiche, sinon la
-- borne se contourne d'elle-meme au fil des imports.
--
-- Les tags hors referentiel V5 sont desactives une fois leurs associations
-- migrees, pas avant, et ne sont pas supprimes : une archive peut encore
-- les porter.
-- =====================================================================

begin;

create temporary table v5_champ (ref text, cle text, libelle text, indication text,
  kind text, requis boolean, position int) on commit drop;
insert into v5_champ select x ->> 'ref', x ->> 'cle', x ->> 'libelle', x ->> 'indication',
  x ->> 'kind', (x ->> 'requis')::boolean, (x ->> 'position')::int
