delete from public.prompt_fields f using public.prompts p
where f.prompt_id = p.id and p.external_ref like 'rc5-%';

insert into public.prompt_fields (prompt_id, cle, libelle, indication, kind, requis, position)
select p.id, c.cle, c.libelle, c.indication, c.kind::public.prompt_field_kind,
       c.requis, c.position
from v5_champ c join public.prompts p on p.external_ref = c.ref;

do $ctrl$
begin
  if not ((select count(*) from public.prompt_fields f join public.prompts p on p.id = f.prompt_id
        where p.external_ref like 'rc5-%') = 602) then
    raise exception 'Lot 600 : les 602 champs V5 ne sont pas tous poses.';
  end if;
end $ctrl$;

