delete from public.prompt_tags pt using public.prompts p
where pt.prompt_id = p.id and p.external_ref like 'rc5-%';

insert into public.prompt_tags (prompt_id, tag_id)
select p.id, t.id from v5_lien l
join public.prompts p on p.external_ref = l.ref
join public.tags t on t.slug = l.tag
on conflict do nothing;

do $ctrl$
begin
  if not ((select count(*) from public.prompt_tags pt join public.prompts p on p.id = pt.prompt_id
        where p.external_ref like 'rc5-%') = 1418) then
    raise exception 'Lot 600 : les 1418 associations de tags V5 ne sont pas toutes posees.';
  end if;
end $ctrl$;

-- Les tags hors referentiel sortent de la decouverte, maintenant que plus
-- aucune carte active ne les porte. Desactives, pas supprimes.
update public.tags set is_active = false, updated_at = now()
where is_active and groupe not in ('bibliotheque', 'ia')
  and slug not in (select slug from jsonb_to_recordset($raccourcia$[{"slug":"photo"},{"slug":"portrait"},{"slug":"objet"},{"slug":"retouche"},{"slug":"mode"},{"slug":"souvenir"},{"slug":"produit"},{"slug":"publicite"},{"slug":"affiche"},{"slug":"couverture"},{"slug":"marque"},{"slug":"reseaux"},{"slug":"illustration"},{"slug":"anime"},{"slug":"cinema"},{"slug":"humour"},{"slug":"montage"},{"slug":"3d"},{"slug":"retro"},{"slug":"architecture"},{"slug":"plan"},{"slug":"schema"},{"slug":"donnees"},{"slug":"apprentissage"},{"slug":"communication"},{"slug":"synthese"},{"slug":"organisation"},{"slug":"analyse"},{"slug":"recherche"},{"slug":"strategie"},{"slug":"personnage"},{"slug":"debat"},{"slug":"jeu"},{"slug":"enquete"},{"slug":"simulation"},{"slug":"coaching"},{"slug":"quotidien"},{"slug":"finance"},{"slug":"juridique"},{"slug":"code"}]$raccourcia$) as t(slug text))
  and not exists (
    select 1 from public.prompt_tags pt join public.prompts p on p.id = pt.prompt_id
    where pt.tag_id = tags.id and p.status <> 'archived');

commit;
